return ['x-generator'=>'GlotPress/4.0.1','translation-revision-date'=>'2024-07-21 14:39:13+0000','plural-forms'=>'nplurals=2; plural=n != 1;','project-id-version'=>'Plugins - Child Theme Configurator - Stable (latest release)','language'=>'nl','messages'=>['http://www.childthemeplugin.com'=>'http://www.childthemeplugin.com','If you find this plugin useful, please support us by %supgrading%s or %sclick here to donate as little as $1.%s'=>'Als je deze plugin nuttig vindt, kan je ons steunen door %supgraden%s of %s klik hier om slechts $1 te doneren.%s','Dismiss this notice.'=>'Negeer dit bericht.','Help us help you!'=>'Help ons je te helpen!','IMPORTANT: Some "premium" themes use unsupported options that cannot be copied with the free verson of CTC. If you purchased this theme from a website such as "ThemeForest," child themes may not work correctly. Click the "Upgrade" tab for more information.'=>'BELANGRIJK: Sommige \'premium\' thema\'s gebruiken niet ondersteunde opties die niet kunnen worden gekopieerd met de gratis versie van CTC. Als je dit thema hebt gekocht van een site zoals "ThemeForest", werken subthema thema\'s mogelijk niet correct. Klik op de tab "Upgrade" voor meer informatie.','Click to Edit Child Theme Attributes'=>'Klik om subthema attributen te bewerken','Hook Highlighter - See Below The Surface'=>'Hook Highlighter - Kijk onder de oppervlakte','Hook Highlighter - See It In Action'=>'Hook Highlighter - Zie het in actie','<strong>Now with time and memory benchmarks!</strong>'=>'<strong> Nu met tijd- en geheugenbenchmarks! </strong>','Click to edit files using the Theme Editor'=>'Klik om bestanden te bewerken met de Theme Editor','Click to edit functions.php'=>'Klik om functies.php te bewerken','Upgrade Offer'=>'Aanbieding upgraden','Do not force dependency for these stylesheet handles:'=>'Forceer geen afhankelijkheid voor deze stylesheet handles:','Use a relative path to link to webfont kit stylesheets you have uploaded to your Child Theme. <strong>Example:</strong>'=>'Gebruik een relatief pad om te linken naar web lettertype kit stylesheets die je naar je subthema hebt geüpload.<strong>Voorbeeld:</strong>','Local Font Files'=>'Lokale lettertypebestanden','Display action and filter hooks, program files and backtrace information inline for the current page.'=>'Actie en filter hooks, programma bestanden en backtrace informatie inline weergeven voor de huidige pagina.','Hook Highlighter provides insight into the internal program flow of WordPress when activated on any front-facing page of a website.'=>'Hook Highlighter geeft inzicht in de interne programmastroom van WordPress wanneer geactiveerd op een voorpagina van een site.','Learn more about Hook Highlighter'=>'Meer informatie over Hook Highlighter','Maybe you are having trouble getting your child theme to work, or just don’t want to mess with it ... <strong>Let us set it up for you!</strong>'=>'Misschien heb je problemen om het subthema te laten werken, of wil je er gewoon niet mee knoeien ... <strong>Laat het ons voor je regelen!</strong>','Learn more about Premium Support'=>'Meer informatie over Premium-ondersteuning','Additional Linked Stylesheets'=>'Extra gekoppelde stylesheets','Web Fonts & CSS'=>'Weblettertypen en CSS','CTC encountered an error:'=>'CTC heeft een fout aangetroffen:','Error moving file: %s'=>'Fout bij verplaatsen van bestand: %s','Maximum number of styles exceeded.'=>'Maximaal aantal stijlen overschreden.','Pack failed -- %s'=>'Pack mislukt - %s','Unpack failed -- %s'=>'Uitpakken mislukt - %s','newfiles != files'=>'newfiles! = bestanden','deleted: %s != %s files'=>'verwijderd: %s! = %s bestanden','invalid dir: %s'=>'ongeldige map: %s','could not copy %s'=>'kon %s niet kopiëren','Could not copy file: %s'=>'Kan bestand niet kopiëren: %s','<p><strong>The WordPress configuration file has been modified incorrectly.</strong> Please see <a href="http://www.childthemeplugin.com/child-theme-faqs/#constants" target="_blank">this FAQ</a> for more information.</p>'=>'<p><strong>Het WordPress configuratiebestand is onjuist gewijzigd.</strong> Zie <a href="http://www.childthemeplugin.com/child-theme-faqs/#constants" target="_blank">deze FAQ</a> voor meer informatie.</p>','The combination of these two plugins interferes with the Analysis results. Please temporarily deactivate one of them and Analyze again.'=>'De combinatie van deze twee plugins verstoort de analyseresultaten. Schakel een van hen tijdelijk uit en analyseer opnieuw.','Both WP Rocket and Autoptimize plugins are enabled.'=>'Zowel WP Rocket als Autoptimize plugins zijn ingeschakeld.','Use the Web Fonts tab to add a link to the parent RTL stylesheet. See the documentation for more information.</p>'=>'Gebruik de tab Web Fonts om een ​​link toe te voegen aan het hoofd RTL stylesheet. Zie de documentatie voor meer informatie</p>.','This theme uses a RTL (right-to-left) stylesheet that is not being loaded in the child theme.'=>'Dit thema gebruikt een RTL stijlblad (van rechts naar links) dat niet in het subthema wordt geladen.','<p><strong>PLEASE NOTE:</strong></p><p><em>The analyzer reveals errors that may otherwise go undetected. Unless this is a fatal error, WordPress may appear to work correctly; however, PHP will continue to log the error until it is resolved. Please contact the author of any theme or plugin</em> <strong>mentioned above</strong> <em>and cut/paste the error from the text area.</em> <strong>Do not use a screen capture as it may cut off part of the error text.</strong> <em>Additional information about the error may also be available in the <a href="http://www.childthemeplugin.com/child-theme-faqs/" target="_blank">CTC documentation</a>.</em></p>'=>'<p><strong>LET OP:</strong></p> <p><em>De analyser onthult fouten die anders onopgemerkt zouden blijven. Tenzij dit een fatale fout is, kan WordPress correct lijken te werken; PHP blijft de fout echter vastleggen totdat deze is opgelost. Neem contact op met de auteur van een thema of plugin</em> <strong>hierboven genoemd</strong> <em>en knip/plak de fout uit het tekstgebied.</em> <strong>Gebruik geen schermopname als het kan een deel van de fouttekst afsnijden.</strong> <em>Aanvullende informatie over de fout is mogelijk ook beschikbaar in de <a href="http://www.childthemeplugin.com/child-theme-faqs/" target="_blank">CTC-documentatie</a>.</em></p>','<p>This workaround was used in earlier versions of CTC and can be eliminated by using the "Repair header template" option (see step 6, "Additional handling options", below).</p>'=>'<p> Deze oplossing werd in eerdere versies van CTC gebruikt en kan worden geëlimineerd met behulp van de optie "Headertemplate herstellen" (zie stap 6, "Aanvullende behandelingsopties", hieronder). </p>','This Child Theme was configured to accomodate a hard-coded stylesheet link.'=>'Dit subthema is geconfigureerd om een ​​hard-coded stylesheet link te bevatten.','By default, the order of stylesheets that load prior to the primary stylesheet is preserved by treating them as dependencies. In some cases, stylesheets are detected in the preview that are not used site-wide. If necessary, dependency can be removed for specific stylesheets above.'=>'Standaard wordt de volgorde van stylesheets die vóór het primaire stylesheet worden geladen, behouden door ze als afhankelijkheden te behandelen. In sommige gevallen worden stylesheets in het voorbeeld gedetecteerd die niet voor de hele site worden gebruikt. Indien nodig kan afhankelijkheid worden verwijderd voor specifieke stylesheets hierboven.','Advanced handling options'=>'Geavanceerde afhandelingsopties','Update Plugin'=>'Update plugin','Upgrade Now'=>'Nu upgraden','You can upgrade to the latest version by clicking the button below. After validating the Update Key from your order, WordPress will retrieve the plugin from our website and install it automatically. If you no longer wish to use the premium version, you can dismiss this notice by clicking the close icon (x) at the top right.'=>'Je kunt upgraden naar de nieuwste versie door op de onderstaande knop te klikken. Na het valideren van de update sleutel van je bestelling, haalt WordPress de plugin op van onze site en installeert deze automatisch. Als je de premium versie niet langer wil gebruiken, kun je deze melding afwijzen door op het sluit pictogram (x) rechtsboven te klikken.',' is not compatible with the installed version of Child Theme Configurator and has been deactivated.'=>' is niet compatibel met de geïnstalleerde versie van Child Theme Configurator en is gedeactiveerd.','Child Theme Configurator Pro version %s'=>'Child Theme Configurator Pro versie %s','contact us.'=>'Neem contact op.','Sorry, we could not validate your Update Key. Please try again or, if you need assistance, please %s'=>'We kunnen je update sleutel niet valideren. Probeer het opnieuw of, als je hulp nodig hebt, %s','Enter your Update Key'=>'Voer je update sleutel in','Export Child Theme'=>'Subthema exporteren','%sPreview your child theme%s before activating.'=>'%sBekijk je subthema %s voordat je het activeert.','You must %sNetwork enable%s your child theme.'=>'Je moet %sNetwork inschakelen%s van je subthema.','Update Key saved successfully.'=>'Update sleutel succesvol opgeslagen.','To find and edit selectors containing specific values for a given property, first choose the property (e.g., "color"), then click "Selectors" for any resulting value. A dialog panel will open with the corresponding selectors, grouped by media query.'=>'Om selectors te zoeken en te bewerken die specifieke waarden voor een bepaalde eigenschap bevatten, kies je eerst de eigenschap (bijvoorbeeld "kleur") en klik je vervolgens op "Selectors" voor een resulterende waarde. Er wordt een dialoogvenster geopend met de bijbehorende kiezers, gegroepeerd op mediaquery.','To find and edit specific selectors within @media query blocks, first choose the query, then the selector. Use the "base" query to edit all other selectors.'=>'Om specifieke selectors binnen @media-queryblokken te vinden en te bewerken, kies je eerst de query en vervolgens de selector. Gebruik de "base" query om alle andere selectors te bewerken.','It is a good idea to save a Zip Archive of your Child Theme before using CTC for the first time. Click the "save backup" link ( see Step 2, below ) to export your themes.'=>'Het is een goed idee om een ​​Zip archief van je subthema op te slaan voordat je CTC voor het eerst gebruikt. Klik op de link "back-up opslaan" (zie stap 2 hieronder) om je thema\'s te exporteren.','Thank you for installing Child Theme Configurator.'=>'Bedankt voor het installeren van Child Theme Configurator.','Create new template and script files right from the admin.'=>'Maak rechtstreeks vanuit de beheerder nieuwe template en script bestanden.','Add Child Theme Files'=>'Subthema bestanden toevoegen','<p>%1Click Here%2 to view the theme as viewed by the Analyzer.</p>'=>'<p>% 1Klik hier% 2 om het thema te bekijken zoals bekeken door de Analyzer. </p>','Click to show/hide raw analysis data. Please include contents below with any support requests.'=>'Klik om onbewerkte analysegegevens weer te geven/te verbergen. Voeg de onderstaande inhoud bij alle ondersteuningsverzoeken.','Click to show/hide PHP debug output'=>'Klik om de PHP debug output te tonen/verbergen','<p>First, verify you can <a href="%s">preview your home page with the Customizer</a> and try analyzing again.</p><p>If that does not work, try temporarily disabling plugins that <strong>minify CSS</strong> or that <strong>force redirects between HTTP and HTTPS</strong>.</p>'=>'<p>Controleer eerst of je <a href="%s"> een voorbeeld van je voorpagina kunt bekijken met de Customizer </a> en probeer opnieuw te analyseren.</p> <p>Als dat niet werkt, probeer dan tijdelijk plugins uit te schakelen die<strong> CSS verkleinen </strong>of die<strong> omleidingen tussen HTTP en HTTPS forceren</strong></p>.','Click here to save a backup of the selected theme.'=>'Klik hier om een ​​back-up van het geselecteerde thema op te slaan.','Click "Export Zip" to save a backup of the currently loaded child theme. You can export any of your themes from the Parent/Child tab.'=>'Klik op "Zip exporteren" om een ​​back-up van het momenteel geladen subthema op te slaan. Je kunt al je thema\'s exporteren vanaf de tab Hoofd/Sub.','This Child Theme has incorrect ownership permissions. Child Theme Configurator will attempt to correct this when you click the button below.'=>'Dit subthema heeft onjuiste eigendomsrechten. Child Theme Configurator probeert dit te corrigeren wanneer je op de onderstaande knop klikt.','The theme "%s" could not be analyzed because the preview did not render correctly.'=>'Het thema " %s" kon niet worden geanalyseerd omdat het voorbeeld niet correct werd weergegeven.','Invalid theme root directory.'=>'Ongeldige thema root folder.','PclZip returned zero bytes.'=>'PclZip heeft nul bytes geretourneerd.','No writable temp directory.'=>'Geen beschrijfbare tijdelijke map.','<p>The Configurator selected "Do not add any parent stylesheet handling" for the "Parent stylesheet handling" option (see step 6, below).</p>'=>'<p>De geselecteerde Configurator heeft "Geen verwerking van hoofd stylesheet" toegevoegd voor de optie "Verwerking van hoofd stylesheet" (zie stap 6 hieronder)</p>.','When using the Customizer is not enough - Create child themes and customize styles, templates, functions and more.'=>'Wanneer het gebruik van de customizer niet genoeg is - Maak subthema\'s en pas stijlen, \'templates, functies en meer aan.','Child Styles'=>'Sub stijlen','Baseline Styles'=>'Basislijnstijlen','Baseline Value'=>'Basiswaarde','( or "base" )'=>'(of "basis")','@media Query'=>'@media Query','Configure Plugin Styles'=>'Plugin stijlen configureren','Select the plugin stylesheets you wish to customize below.'=>'Selecteer hieronder de plugin stylesheets die je wilt aanpassen.','Parse Plugin stylesheets:'=>'Parse plugin stylesheets:','Configure Child Theme'=>'Subthema configureren','Click to run the Configurator:'=>'Klik om de Configurator uit te voeren:','This option replaces the Child Theme\'s existing Menus, Widgets and other Customizer Settings with those from the Parent Theme. You should only need to use this option the first time you configure a Child Theme.'=>'Deze optie vervangt de bestaande menu\'s, widgets en andere customizer instellingen van het subthema door die van het hoofd thema. Je zou deze optie alleen moeten gebruiken als je voor het eerst een subthema configureert.','Copy Menus, Widgets and other Customizer Settings from the Parent Theme to the Child Theme:'=>'Kopieer menu\'s, widgets en andere customizer instellingen van het hoofd thema naar het subthema:','Customize the Child Theme Name, Description, Author, Version, etc.:'=>'Pas de naam, beschrijving, auteur, versie, enz. van het subthema aan:','Click to toggle form'=>'Klik om van formulier te wisselen','Let the Configurator (try to) resolve any stylesheet issues listed above. This can fix many, but not all, common problems.'=>'Laat de Configurator alle bovengenoemde problemen met stylesheets oplossen. Dit kan veel, maar niet alle, veelvoorkomende problemen oplossen.','Repair the header template in the child theme.'=>'Herstel de header template in het subthema.','Do not load or parse the parent theme styles. Only use this option if the Child Theme uses a Framework like Genesis and uses <em>only child theme stylesheets</em> for its appearance.'=>'Laad of ontleed de hoofd thema stijlen niet. Gebruik deze optie alleen als het subthema een Framework zoals Genesis gebruikt en <em>alleen subthema stylesheets</em> gebruikt voor zijn weergave.','Ignore parent theme stylesheets.'=>'Negeer stijlbladen voor hoofd thema\'s.','Select this option if this theme already handles the parent theme stylesheet or if the parent theme\'s <code>style.css</code> file is not used for its appearance.'=>'Selecteer deze optie als dit thema de stijl van het hoofd thema al verwerkt of als het <code>style.css</code> bestand van het hoofd thema\'s niet wordt gebruikt voor zijn weergave.','Do not add any parent stylesheet handling.'=>'Voeg geen verwerking van hoofd stylesheets toe.','Only use this option if the parent stylesheet cannot be loaded using the WordPress style queue. Using <code>@import</code> is not recommended.'=>'Gebruik deze optie alleen als het hoofd stylesheet niet kan worden geladen met de wachtrij in WordPress stijl. Het gebruik van <code>@import</code> wordt niet aanbevolen.','Use <code>@import</code> in the child theme stylesheet.'=>'Gebruik <code>@import</code> in het subthema stylesheet.','Let the Configurator determine the appropriate actions and dependencies and update the functions file automatically.'=>'Laat de configurator de juiste acties en afhankelijkheden bepalen en het functie bestand automatisch updaten.','Use the WordPress style queue.'=>'Gebruik de WordPress stijl wachtrij.','Select Parent Theme stylesheet handling:'=>'Selecteer Afhandeling van stylesheet voor hoofd thema:','Save new custom styles to a separate stylesheet and combine any existing child theme styles with the parent to form baseline. Select this option if you want to preserve the existing child theme styles instead of overwriting them. This option also allows you to customize stylesheets that load after the primary stylesheet.'=>'Sla nieuwe aangepaste stijlen op in een afzonderlijk stijlblad en combineer alle bestaande subthema stijlen met het hoofd om de basislijn te vormen. Selecteer deze optie als je de bestaande subthema stijlen wilt behouden in plaats van ze te overschrijven. Met deze optie kun je ook stylesheets aanpassen die na het primaire stylesheet worden geladen.','Separate Stylesheet'=>'Afzonderlijk stylesheet','Save new custom styles directly to the Child Theme primary stylesheet, replacing the existing values. The primary stylesheet will load in the order set by the theme.'=>'Sla nieuwe aangepaste stijlen rechtstreeks op in het primaire stijlblad van het subthema en vervang de bestaande waarden. Het primaire stylesheet wordt geladen in de volgorde die is ingesteld door het thema.','Primary Stylesheet (style.css)'=>'Primaire stylesheet (style.css)','Select where to save new styles:'=>'Selecteer waar je nieuwe stijlen wilt opslaan:','Click to expand'=>'Klik om uit te breiden','For verification only (you cannot modify the directory of an existing Child Theme).'=>'Alleen ter verificatie (je kunt de folder van een bestaand subthema niet wijzigen).','Verify Child Theme directory:'=>'Controleer de folder van het subthema:','This is NOT the name of the Child Theme. You can customize the name, description, etc. in step 7, below.'=>'Dit is NIET de naam van het subthema. Je kunt de naam, beschrijving enz. aanpassen in stap 7 hieronder.','Directory Name'=>'Folder naam','Name the new theme directory:'=>'Geef de nieuwe thema folder een naam:','Analyze Child Theme'=>'Subthema analyseren','Select a Child Theme:'=>'Selecteer een subthema:','Click "Analyze" to determine stylesheet dependencies and other potential issues.'=>'Klik op "Analyseren" om de afhankelijkheden van stylesheets en andere potentiële problemen te bepalen.','Analyze Parent Theme'=>'Hoofd thema analyseren','Analyze'=>'Analiseren','Select a Parent Theme:'=>'Selecteer een hoofd thema:','Revert the Child theme stylesheet and functions files to their state before the initial configuration or last reset. Additional child theme files will not be removed, but you can delete them under the Files tab.'=>'Zet het subthema stylesheet en de functie bestanden terug naar hun staat vóór de initiële configuratie of de laatste reset. Extra subthema bestanden worden niet verwijderd, maar je kunt ze verwijderen onder de tab Bestanden.','RESET an existing Child Theme (this will destroy any work you have done in the Configurator)'=>'RESET een bestaand subthema (dit zal al het werk dat je in de Configurator hebt gedaan vernietigen)','Make a complete copy of an existing Child Theme in a new directory, including any menus, widgets and other Customizer settings. The option to copy the Parent Theme settings (step 8, below) is disabled with this action.'=>'Maak een volledige kopie van een bestaand subthema in een nieuwe folder, inclusief eventuele menu\'s, widgets en andere customizer instellingen. De optie om de instellingen voor het hoofd thema te kopiëren (stap 8 hieronder) is uitgeschakeld met deze actie.','DUPLICATE an existing Child Theme'=>'Een bestaand subthema DUPLICEREN','Set up a previously installed child theme for use with the Configurator or to modify current settings.'=>'Stel een eerder geïnstalleerd subthema in voor gebruik met de Configurator of om de huidige instellingen te wijzigen.','CONFIGURE an existing Child Theme'=>'CONFIGUREER een bestaand subthema','Install a new customizable child theme using an installed theme as a parent.'=>'Installeer een nieuw aanpasbaar subthema met een geïnstalleerd thema als hoofd.','CREATE a new Child Theme'=>'MAAK een nieuw subthema','Select an action:'=>'Selecteer een actie:','Currently loaded'=>'Momenteel geladen','Copy PHP templates from the parent theme by selecting them here. The Configurator defines a template as a Theme PHP file having no PHP functions or classes. Non-template files cannot be inherited by a child theme.'=>'Kopieer PHP templates uit het hoofd thema door ze hier te selecteren. De configurator definieert een template als een PHP thema bestand zonder PHP functies of klassen. Niet-template bestanden kunnen niet worden overgenomen door een subthema.','click here to view the latest videos.'=>'klik hier om de nieuwste video\'s te bekijken.','For more information, please open the Help tab at the top right or '=>'Open voor meer informatie de tab Hulp in de rechterbovenhoek of ','Contact Us.'=>'Neem contact op.','A lot of time and testing has gone into this release but there may be edge cases. If you have any questions, please'=>'Deze release heeft veel tijd en tests gekost, maar er kunnen randgevallen zijn. Als je vragen heeft,','Your stylesheet has changed since the last time you used the Configurator. Please follow the steps for "CONFIGURE an existing Child Theme" under the "Parent/Child" Tab or you will lose these changes.'=>'Je stylesheet is gewijzigd sinds de laatste keer dat je de Configurator gebruikte. Volg de stappen voor "CONFIGUREER een bestaand subthema" onder de tab "Hoofd/sub", anders verlies je deze wijzigingen.','Child Theme Configurator did not detect any configuration data because a previously configured Child Theme has been removed. Please follow the steps for "CONFIGURE an existing Child Theme" under the "Parent/Child" Tab.'=>'Child Theme Configurator heeft geen configuratiegegevens gedetecteerd omdat een eerder geconfigureerd subthema is verwijderd. Volg de stappen voor "CONFIGUREER een subthema" onder het tabblad "Hoofd/Sub".','<p>This method has been replaced by the "Separate stylesheet" and "Ignore Parent Theme" options ( selected below ) for broader framework compatability.</p>'=>'<p>Deze methode is vervangen door de opties "Afzonderlijk stijlblad" en "Negeer hoofd thema" (hieronder geselecteerd) voor een bredere compatibiliteit van het framework.</p>','This child theme was configured using the CTC Pro "Genesis stylesheet handling" method.'=>'Dit subthema was geconfigureerd met de CTC Pro "Genesis stylesheet handling" methode.','This theme does not require the parent theme\'s <code>style.css</code> file for its appearance.'=>'Voor dit thema is het <code>style.css</code> bestand van het hoofd thema niet vereist voor de weergave.','The parent theme\'s <code>style.css</code> file is being loaded automatically.'=>'Het <code>style.css</code> bestand van het hoofd thema wordt automatisch geladen.','<p>Consider saving new custom styles to a "Separate stylesheet" (see step 5, below) so that you can customize these styles.</p>'=>'<p> Overweeg om nieuwe aangepaste stijlen op te slaan in een "Afzonderlijk stijlblad" (zie stap 5 hieronder), zodat je deze stijlen kunt aanpassen. </p>','This theme loads additional stylesheets after the <code>style.css</code> file:'=>'Dit thema laadt extra stylesheets na het <code> style.css </code>bestand:','<p>Please consider selecting "Use the WordPress style queue" for the parent stylesheet handling option (see step 6, below).</p>'=>'<p>Overweeg om "Gebruik de WordPress stijl wachtrij" te selecteren voor de hoofdafhandeling optie voor het stijlblad (zie stap 6 hieronder)</p>.','This child theme uses <code>@import</code> to load the parent theme\'s <code>style.css</code> file.'=>'Dit subthema gebruikt <code>@import</code> om het <code>style.css</code>bestand van het hoofd thema te laden.','<p>The Configurator makes significant modifications to the child theme, including stylesheet changes and additional php functions. Please consider using the DUPLICATE child theme option (see step 1, above) and keeping the original as a backup.</p>'=>'<p>De Configurator brengt aanzienlijke wijzigingen aan in het subthema, inclusief wijzigingen in de stylesheet en extra PHP functies. Overweeg om de optie DUBBEL subthema te gebruiken (zie stap 1 hierboven) en het origineel als back-upte bewaren</p>.','This Child Theme has not been configured for this plugin.'=>'Dit subthema is niet geconfigureerd voor deze plugin.','This theme appears OK to use as a Child theme.'=>'Dit thema lijkt OK om als subthema te gebruiken.','This child theme appears to be functioning correctly.'=>'Dit subthema lijkt correct te werken.','<p>Please select a stylesheet handling method or check "Ignore parent theme stylesheets" (see step 6, below).</p>'=>'<p>Selecteer een verwerkingsmethode voor een stylesheet of vink "Negeer stylesheets voor hoofd thema\'s" aan (zie stap 6 hieronder)</p>.','This child theme uses the parent stylesheet but does not load the parent theme\'s <code>style.css</code> file.'=>'Dit subthema gebruikt het hoofd stylesheet maar laadt het <code>style.css</code> bestand van het hoofd thema niet.','<p>If you want to customize styles using this plugin, please click "Configure Child Theme" again to add this to the settings.</p>'=>'<p>Als je stijlen wilt aanpassen met deze plugin, klik je nogmaals op "Subthema configureren" om dit aan de instellingen toe te voegen</p>.','This child theme does not load a Configurator stylesheet.'=>'Dit subthema laadt geen configurator stylesheet.','<p>This is common with older themes but requires the use of <code>@import</code>, which is no longer recommended. You can try to resolve this using the "Repair header template" option (see step 6, "Additional handling options", below).</p>'=>'<p> Dit komt vaak voor bij oudere thema\'s, maar vereist het gebruik van <code> @import </code>, wat niet langer wordt aanbevolen. Je kunt proberen dit op te lossen met behulp van de optie "Headertemplate herstellen" (zie stap 6, "Aanvullende behandelingsopties", hieronder). </p>','This theme loads the parent theme\'s <code>style.css</code> file outside the wp_styles queue.'=>'Dit thema laadt het <code> style.css </code>bestand van het hoofd thema buiten de wachtrij wp_styles.','<p>This makes it difficult for plugins to override these styles. You can try to resolve this using the  "Repair header template" option (Step 6, "Additional handling options", below).</p>'=>'<p>Dit maakt het moeilijk voor plugins om deze stijlen te overschrijven. Je kunt proberen dit op te lossen door gebruik te maken van de "Header template herstellen" (stap 6, "Extra behandelingsopties", hieronder)</p>.','This theme loads stylesheets after the wp_styles queue.'=>'Dit thema laadt stylesheets na de wp_styles wachtrij.','Do Not Activate "%s"! A PHP FATAL ERROR has been detected.'=>'Activeer " %s" niet! Er is een PHP FATAL ERROR gedetecteerd.','The theme "%s" generated unexpected PHP debug output.'=>'Het thema "%s" genereerde onverwachte PHP fout opsporing uitvoer.','Checking'=>'Controleren','Updating'=>'Aan het updaten','No Styles Available. Check Parent/Child settings.'=>'Geen stijlen beschikbaar. Controleer de instellingen voor hoofd/sub.','Are you sure you wish to RESET? This will destroy any work you have done in the Configurator.'=>'Weet je zeker dat je wilt RESETTEN? Dit vernietigt al het werk dat je in de Configurator heeft gedaan.','Child Theme <strong>%s</strong> has been generated successfully.'=>'Child Theme <strong> %s </strong> is met succes gegenereerd.','Child Theme <strong>%s</strong> has been reset. Please configure it using the settings below.'=>'Child Theme <strong> %s </strong> is gereset. Configureer het met de onderstaande instellingen.','Lorem ipsum dolor sit amet, consectetur adipiscing elit.'=>'Lorem ipsum dolor sit amet, consectetur adipiscing elit.','Could not upgrade child theme'=>'Kan subthema niet upgraden','Please select a valid Child Theme.'=>'Selecteer een geldig subthema.','http://www.lilaeamedia.com'=>'http://www.lilaeamedia.com','Lilaea Media'=>'Lilaea Media','Use <code>@import url( [path] );</code> to link additional stylesheets. Child Theme Configurator uses the <code>@import</code> keyword to identify them and convert them to <code>&lt;link&gt;</code> tags. <strong>Example:</strong>'=>'Gebruik <code>@import url( [path] );</code> om additionele stylesheets te linken. Child Theme Configurator gebruikt <code>@import</code> keyword om ze te identificeren en te converteren naar<code>&lt;link&gt;</code> tags. <strong>Voorbeeld:</strong>','Not Network Enabled'=>'Niet netwerk ingeschakeld',' in default Site'=>' in standaard site','Preview'=>'Voorbeeld','By: '=>'Door: ','Version: '=>'Versie: ','Files'=>'Bestanden','Property/ Value'=>'Eigenschap/waarde','Query/ Selector'=>'Query/Selector','Parent/ Child'=>'Hoofd/sub','Value'=>'Waarde','Click help'=>'Klik op Help','New user?'=>'Nieuwe gebruiker?','Values entered here are merged into existing child styles or added to the child stylesheet if they do not exist in the parent.'=>'Waarden die hier zijn ingevoerd, worden samengevoegd met bestaande subthema stijlen of toegevoegd aan het subthema stylesheet als ze niet bestaan ​​in het hoofd.','Use to enter shorthand CSS or new @media queries and selectors.'=>'Gebruik om steno CSS of nieuwe @media-zoekopdrachten en selectors in te voeren.','Raw CSS'=>'Raw CSS','Save'=>'Opslaan','Copy Selector'=>'Kopie kiezer','Order'=>'Bestellen','New Property'=>'Nieuwe eigenschap','Child Value'=>'Subthema waarde','Property'=>'Eigenschap','Delete Child Values'=>'Subthema waarden verwijderen','Save Child Values'=>'Subthema waarden opslaan','Sample'=>'Monster','Selector'=>'Selector','Debug'=>'Debuggen','NOTE:'=>'NOTITIE:','Version'=>'Versie','Tags'=>'Tags','Theme Tags'=>'Thema tags','Description'=>'Beschrijving','Theme Description'=>'Thema Beschrijving','Author Website'=>'Auteur site','Author'=>'Auteur','Theme Website'=>'Thema site','Theme Name'=>'Thema naam','Child Theme Name'=>'Naam van subthema','version'=>'versie','Delete child theme images by selecting them here.'=>'Verwijder afbeeldingen van subthema\'s door ze hier te selecteren.','Child Theme Images'=>'Child Theme Images','Make read-only'=>'Alleen-lezen maken','Attempt to reset child theme permissions to user ownership and read-only access.'=>'Probeer de rechten voor subthema\'s opnieuw in te stellen op eigendom van de gebruiker en alleen-lezen toegang.','Secure Child Theme'=>'Beveiligd subthema','Export Child Theme as Zip Archive'=>'Subthema exporteren als zip archief','The theme screenshot should be a 4:3 ratio (e.g., 880px x 660px) JPG, PNG or GIF. It will be renamed <code>screenshot</code>.'=>'De thema schermafbeelding moet een verhouding van 4: 3 zijn (bijvoorbeeld 880px x 660px) JPG, PNG of GIF. Het wordt hernoemd <code>schermafbeelding</code>.','Upload New Screenshot'=>'Nieuwe schermafbeelding uploaden','Child Theme Screenshot'=>'Schermafbeelding subthema','Upload'=>'Uploaden','Theme images reside under the <code>images</code> directory in your child theme and are meant for stylesheet use only. Use the Media Library for content images.'=>'Thema afbeeldingen bevinden zich in de <code>afbeeldingen</code> folder in je subthema en zijn alleen bedoeld voor gebruik in stylesheets. Gebruik de mediabibliotheek voor inhoud afbeeldingen.','Upload New Child Theme Image'=>'Nieuwe subthema afbeelding uploaden','Delete Selected'=>'Verwijder geselecteerde','Copy Selected to Child Theme'=>'Geselecteerde kopiëren naar subthema','Make Selected Writable'=>'Geselecteerde beschrijfbaar maken','Delete child theme templates or make them writable by selecting them here. Writable files are displayed in <span style="color:red">red</span>.'=>'Verwijder subthema templates of maak ze beschrijfbaar door ze hier te selecteren. Beschrijfbare bestanden worden weergegeven in <span style="color:red">rood</span>.','Delete child theme templates by selecting them here.'=>'Verwijder subthema templates door ze hier te selecteren.','The %s file is generated separately and cannot be copied here.'=>'Het %s bestand wordt afzonderlijk gegenereerd en kan hier niet worden gekopieerd.','CAUTION: If your child theme is active, the child theme version of the file will be used instead of the parent immediately after it is copied.'=>'LET OP: als het sub-thema actief is, wordt desub-thema versie van het bestand gebruikt in plaats van de parent direct nadat het is gekopieerd.','Child Theme Files'=>'Child Theme Files','Parent Templates'=>'Hoofd templates','Click here to edit template files using the Theme Editor'=>'Klik hier om template bestanden te bewerken met de thema editor','The Theme editor has been disabled. Template files must be edited offline.'=>'De thema editor is uitgeschakeld. Template bestanden moeten offline worden bewerkt.','Restore backup from'=>'Back-up terugzetten van','Backup'=>'Back-up','Upgrade'=>'Upgrade','Tutorial Videos'=>'Instructievideo\'s','Online Documentation'=>'Online documentatie','Top-rated Online Support'=>'Hoogwaardige online ondersteuning','Return to recently edited selectors from a toggleable sidebar.'=>'Keer terug naar recent bewerkte selectors vanuit een schakelbare zijbalk.','Most recent edits'=>'Meest recente bewerkingen','Tweak menus quickly and easily.'=>'Tweak menu\'s snel en gemakkelijk.','Find styles by Nav Menu'=>'Stijlen zoeken via Nav Menu','Use the "All Styles" panel to edit groups of selectors from a single combined list.'=>'Gebruik het paneel "Alle stijlen" om groepen kiezers uit één gecombineerde lijst te bewerken.','Find related styles'=>'Gerelateerde stijlen zoeken','Keep the colors you select just a click away. No more searching for hex codes and RGB values.'=>'Houd de kleuren die je selecteert slechts een muisklik verwijderd. Nooit meer zoeken naar hex codes en RGB waarden.','Color Palettes'=>'Kleurenpaletten','Preview your child theme with a single click.'=>'Bekijk een voorbeeld van je subthema met een enkele klik.','Quick Preview'=>'Snel voorbeeld','Apply the power of CTC\'s top-rated interface to your site\'s plugin styles. All new design makes it much easier to get the results you want.'=>'Pas de kracht van de best beoordeelde interface van CTC toe op de plugin-stijlen van je site. Een geheel nieuw ontwerp maakt het veel gemakkelijker om de gewenste resultaten te krijgen.','Customize Plugin Stylesheets'=>'Plugin Stylesheets aanpassen','We\'ve packed in more features to make design work quicker and easier with <strong>Child Theme Configurator Pro.</strong>'=>'We hebben meer functies toegevoegd om het ontwerp sneller en gemakkelijker te laten werken met <strong>Child Theme Configurator Pro.</strong>','Designed by Developers Who Use It Every Day.'=>'Ontworpen door ontwikkelaars die het elke dag gebruiken.','Thousands of users have already seen the benefits of using Child Theme Configurator. If you spend any amount of time customizing WordPress, CTC Pro will help maximize your productivity.'=>'Duizenden gebruikers hebben de voordelen van het gebruik van Child Theme Configurator al gezien. Als je enige tijd besteedt aan het aanpassen van WordPress, helpt CTC Pro je productiviteit te maximaliseren.','Customizing WordPress just got even easier.'=>'Het aanpassen van WordPress is nu nog eenvoudiger geworden.','Learn more about CTC Pro'=>'Meer informatie over CTC Pro','Learn more'=>'Meer informatie','*Prices and offers subject to change.'=>'* Prijzen en aanbiedingen onder voorbehoud.','Order Now'=>'Bestel nu','and get <strong>20% off entire order</strong>.'=>'en ontvang <strong> 20% korting op hele bestelling </strong>.','wordpress-org'=>'wordpress-org','Use coupon code'=>'Gebruik waardebon','Stylesheets that are currently being loaded by the parent theme are automatically selected below (except for Bootstrap stylesheets which add a large amount data to the configuration). To further reduce overhead, select only the additional stylesheets you wish to customize.'=>'Stylesheets die momenteel door het hoofd thema worden geladen, worden hieronder automatisch geselecteerd (behalve Bootstrap stylesheets die een grote hoeveelheid gegevens aan de configuratie toevoegen). Selecteer alleen de aanvullende stylesheets die je wil aanpassen om de overhead verder te verminderen.','Parse additional stylesheets:'=>'Aanvullende stylesheets parsen:','<strong>However, some styles could not be parsed due to memory limits.</strong> Try deselecting "Additional Stylesheets" below and click "Generate/Rebuild Child Theme Files". %sWhy am I seeing this?%s'=>'<strong>Sommige stijlen konden echter niet worden geparseerd vanwege geheugenlimieten.</strong> Schakel hieronder "Extra stylesheets" uit en klik op "Genereer/herbouw subthema bestanden". %sWaarom zie ik dit? %s','Child Theme Configurator needs to update its internal data. Please set your preferences below and click "Generate Child Theme Files" to update your configuration.'=>'Child Theme Configurator moet zijn interne gegevens updaten. Stel hieronder je voorkeuren in en klik op "Genereer subthema bestanden" om je configuratie  te updaten.','Correct Child Theme Permissions'=>'Machtigingen voor subthema\'s corrigeren','<li>Run PHP under Apache with suEXEC (contact your web host).</li>'=>'<li>Voer PHP uit onder Apache met suEXEC (neem contact op met je webhost).</li>','<li><a target="_blank" href="http://codex.wordpress.org/Changing_File_Permissions" title="Changing File Permissions">Set write permissions on the server manually</a> (not recommended).</li>'=>'<li><a target="_blank" href="http://codex.wordpress.org/Changing_File_Permissions" title="Changing File Permissions">Stel handmatig schrijfrechten in op de server</a> (niet aanbevolen).</li>','<li><a target="_blank" href="http://technet.microsoft.com/en-us/library/cc771170" title="Setting Application Pool Identity">Assign WordPress to an application pool that has write permissions</a> (Windows IIS systems).</li>'=>'<li><a target="_blank" href="http://technet.microsoft.com/en-us/library/cc771170" title="Setting Application Pool Identity">Wijs WordPress toe aan een toepassingsgroep met schrijfrechten</a> (Windows IIS-systemen).</li>','<li><a target="_blank"  href="http://codex.wordpress.org/Editing_wp-config.php#WordPress_Upgrade_Constants" title="Editin wp-config.php">Add your FTP/SSH credentials to the WordPress config file</a>.</li>'=>'<li><a target="_blank" href="http://codex.wordpress.org/Editing_wp-config.php#WordPress_Upgrade_Constants" title="Editin wp-config.php"> Voeg je toe FTP/SSH-gegevens voor het WordPress-configuratiebestand </a>. </li>','Make files writable'=>'Bestanden beschrijfbaar maken','<li>Temporarily set write permissions by clicking the button below. When you are finished editing, revert to read-only by clicking "Make read-only" under the "Files" tab.</li>'=>'<li>Stel tijdelijk schrijfrechten in door op de onderstaande knop te klikken. Wanneer je klaar bent met bewerken, keert je terug naar alleen-lezen door te klikken op "Maak alleen-lezen" op de tab "Bestanden"</li>.','The child theme is in read-only mode and Child Theme Configurator cannot apply changes. Click to see options'=>'Het subthema staat in de modus alleen-lezen en Child Theme Configurator kan geen wijzigingen toepassen. Klik om opties te zien','Could not upload file.'=>'Kan bestand niet uploaden.','There were errors while resetting permissions.'=>'Er zijn fouten opgetreden bij het opnieuw instellen van rechten.','Could not set write permissions.'=>'Kan geen schrijfrechten instellen.','Could not delete %s file.'=>'Kan %s bestand niet verwijderen.','A closing PHP tag was detected in Child theme functions file so "Parent Stylesheet Handling" option was not configured. Closing PHP at the end of the file is discouraged as it can cause premature HTTP headers. Please edit <code>functions.php</code> to remove the final <code>?&gt;</code> tag and click "Generate/Rebuild Child Theme Files" again.'=>'Er is een afsluitende PHP tag gedetecteerd in het bestand functies van het subthema waardoor de optie "Hoofd stylesheet handling" niet is geconfigureerd. Het wordt afgeraden om PHP aan het einde van het bestand te sluiten, omdat dit voortijdige HTTP headers kan veroorzaken. Bewerk <code>functions.php</code> om de laatste <code>?&gt;</code> tag te verwijderen en klik opnieuw op "Genereer/herbouw subthema files".','Your stylesheet is not writable.'=>'Je stylesheet is niet beschrijfbaar.','Your theme directories are not writable.'=>'Je thema folders zijn niet beschrijfbaar.','<strong>%s</strong> exists. Please enter a different Child Theme template name.'=>'<strong>%s</strong> bestaat. Geef een andere naam op voor het subthema template.','Please enter a valid Child Theme directory name.'=>'Voer een geldige folder naam voor het subthema in.','Please select a valid Parent Theme.'=>'Selecteer een geldig hoofd thema.','%s does not exist. Please select a valid Parent Theme.'=>'%s bestaat niet. Selecteer een geldig hoofd thema.','You do not have permission to configure child themes.'=>'Je hebt geen toestemming om subthema\'s te configureren.','The Functions file is required and cannot be deleted.'=>'Het functions bestand is vereist en kan niet worden verwijderd.','Zip file creation failed.'=>'Maken van zip-bestand is mislukt.','%sWhy am I seeing this?%s'=>'%s Waarom zie ik dit? %s','Deactivating or replacing plugins may resolve this issue.'=>'Door het deactiveren of vervangen van plugins kan dit probleem worden opgelost.','Conflicting or out-of-date jQuery libraries were loaded by another plugin:'=>'Conflicterende of verouderde jQuery bibliotheken zijn geladen door een andere plugin:','The page could not be loaded correctly.'=>'De pagina kan niet correct worden geladen.','<strong>%s</strong> exists. Please enter a different Child Theme'=>'<strong>%s</strong> bestaat. Geef een ander subthema op','Please enter a valid Child Theme name.'=>'Voer een geldige naam voor het subthema in.','Please enter a valid Child Theme.'=>'Voer een geldig subthema in.','(Child Only)'=>'(Alleen sub)','The stylesheet cannot be displayed.'=>'De stylesheet kan niet worden weergegeven.','Rename'=>'Naam wijzigen','Cancel'=>'Annuleren','Edit Selector'=>'Selector bewerken','Close'=>'Sluit','Selectors'=>'Selectors','<span style="font-size:10px">!</span>'=>'<span style="font-size:10px">!</span>','Color'=>'Kleur','Style'=>'Stijl','Width/None'=>'Breedte/Geen','Color 2'=>'Kleur 2','Color 1'=>'Kleur 1','Origin'=>'Oorsprong','URL/None'=>'URL/Geen','Live Preview'=>'Live voorbeeld','Go to Themes'=>'Ga naar thema\'s','IMPORTANT:'=>'BELANGRIJK:','Child Theme files modified successfully.'=>'Child Theme bestanden met succes gewijzigd.','Child Theme Configurator requires WordPress version %s or later.'=>'Child Theme Configurator vereist WordPress-versie %s of hoger.','Child Themes'=>'Subthema\'s','Child Theme Configurator'=>'Child Theme Configurator']];